package main

import (
	"crypto/rand"
	"encoding/hex"
	"net/http"
	"sync"
	"time"
)

var (
	sessions = make(map[string]*UserSession)
	mu       sync.RWMutex
)

type UserSession struct {
	UserID      int
	Username    string
	IsLoggedIn  bool
	CreatedAt   time.Time
	IPAddress   string
	UserAgent   string
}

func secureLoginHandler(w http.ResponseWriter, r *http.Request) {
	username := r.FormValue("username")
	password := r.FormValue("password")

	if !validateCredentials(username, password) {
		http.Error(w, "Invalid credentials", http.StatusUnauthorized)
		return
	}

	// SECURE: Invalidate any existing session first
	if oldCookie, err := r.Cookie("session_id"); err == nil {
		mu.Lock()
		delete(sessions, oldCookie.Value)
		mu.Unlock()
	}

	// SECURE: Always generate a NEW session ID after authentication
	newSessionID := generateSecureSessionID()

	mu.Lock()
	sessions[newSessionID] = &UserSession{
		UserID:     getUserID(username),
		Username:   username,
		IsLoggedIn: true,
		CreatedAt:  time.Now(),
		IPAddress:  r.RemoteAddr,
		UserAgent:  r.UserAgent(),
	}
	mu.Unlock()

	// SECURE: Set cookie with all security attributes
	http.SetCookie(w, &http.Cookie{
		Name:     "session_id",
		Value:    newSessionID,
		Path:     "/",
		HttpOnly: true,                    // Prevents JavaScript access
		Secure:   true,                    // HTTPS only
		SameSite: http.SameSiteStrictMode, // CSRF protection
		MaxAge:   3600,                    // 1 hour expiry
	})

	http.Redirect(w, r, "/dashboard", http.StatusFound)
}

func generateSecureSessionID() string {
	b := make([]byte, 32) // 256 bits of entropy
	if _, err := rand.Read(b); err != nil {
		panic("crypto/rand failed")
	}
	return hex.EncodeToString(b)
}

