const express = require('express');
const bcrypt = require('bcrypt');
const pool = require('./db');
const rateLimit = require('express-rate-limit');

const app = express();
app.use(express.json());

// In-memory store (use Redis in production)
const failedAttempts = new Map();

const MAX_FAILED_ATTEMPTS = 5;
const LOCKOUT_DURATION_MS = 15 * 60 * 1000; // 15 minutes
const ATTEMPT_WINDOW_MS = 60 * 60 * 1000; // 1 hour

// Global rate limiter
const loginLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: { error: 'Too many login attempts, please try again later' }
});

function isAccountLocked(username) {
  const attempts = failedAttempts.get(username);
  if (!attempts) return false;

  if (attempts.lockedUntil && Date.now() < attempts.lockedUntil) {
    return true;
  }

  // Clean up expired lockout
  if (attempts.lockedUntil && Date.now() >= attempts.lockedUntil) {
    failedAttempts.delete(username);
  }

  return false;
}

function recordFailedAttempt(username, ip) {
  const now = Date.now();
  let attempts = failedAttempts.get(username) || { count: 0, firstAttempt: now, ips: new Set() };

  // Reset if outside attempt window
  if (now - attempts.firstAttempt > ATTEMPT_WINDOW_MS) {
    attempts = { count: 0, firstAttempt: now, ips: new Set() };
  }

  attempts.count++;
  attempts.ips.add(ip);

  if (attempts.count >= MAX_FAILED_ATTEMPTS) {
    attempts.lockedUntil = now + LOCKOUT_DURATION_MS;
    console.warn(`Account locked: ${username} after ${attempts.count} failed attempts from IPs: ${[...attempts.ips].join(', ')}`);
  }

  failedAttempts.set(username, attempts);
  return attempts.count;
}

function clearFailedAttempts(username) {
  failedAttempts.delete(username);
}

app.post('/api/login', loginLimiter, async (req, res) => {
  const { username, password } = req.body;
  const clientIP = req.ip;

  // Check account lockout first
  if (isAccountLocked(username)) {
    console.warn(`Blocked login attempt for locked account: ${username} from ${clientIP}`);
    return res.status(423).json({ 
      error: 'Account temporarily locked due to too many failed attempts',
      retryAfter: '15 minutes'
    });
  }

  try {
    const result = await pool.query(
      'SELECT id, username, password_hash FROM users WHERE username = $1',
      [username]
    );

    if (result.rows.length === 0) {
      recordFailedAttempt(username, clientIP);
      return res.status(401).json({ error: 'Invalid credentials' });
    }

    const user = result.rows[0];
    const validPassword = await bcrypt.compare(password, user.password_hash);

    if (!validPassword) {
      const attemptCount = recordFailedAttempt(username, clientIP);
      const remaining = MAX_FAILED_ATTEMPTS - attemptCount;

      if (remaining > 0) {
        return res.status(401).json({ 
          error: 'Invalid credentials',
          attemptsRemaining: remaining
        });
      } else {
        return res.status(423).json({ 
          error: 'Account locked due to too many failed attempts'
        });
      }
    }

    // Login successful - clear failed attempts
    clearFailedAttempts(username);

    const token = generateToken(user.id);
    console.info(`Successful login: ${username} from ${clientIP}`);
    res.json({ token });

  } catch (error) {
    console.error('Login error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

