const crypto = require('crypto');

class SecureUserDataEncryptor {
  static ALGORITHM = 'aes-256-gcm';
  static KEY_LENGTH = 32;
  static IV_LENGTH = 16;
  static AUTH_TAG_LENGTH = 16;

  constructor() {
    // Load key from secure environment variable
    const keyBase64 = process.env.DATA_ENCRYPTION_KEY;
    if (!keyBase64) {
      throw new Error('DATA_ENCRYPTION_KEY environment variable not set');
    }

    this.encryptionKey = Buffer.from(keyBase64, 'base64');

    if (this.encryptionKey.length !== SecureUserDataEncryptor.KEY_LENGTH) {
      throw new Error('Invalid encryption key length');
    }
  }

  encryptUserData(userData) {
    // Generate random IV for each encryption operation
    const iv = crypto.randomBytes(SecureUserDataEncryptor.IV_LENGTH);

    const cipher = crypto.createCipheriv(
      SecureUserDataEncryptor.ALGORITHM,
      this.encryptionKey,
      iv
    );

    const plaintext = JSON.stringify(userData);
    let encrypted = cipher.update(plaintext, 'utf8', 'hex');
    encrypted += cipher.final('hex');

    // Get authentication tag for integrity verification
    const authTag = cipher.getAuthTag();

    // Return IV + AuthTag + Ciphertext (all needed for decryption)
    return {
      iv: iv.toString('hex'),
      authTag: authTag.toString('hex'),
      data: encrypted
    };
  }

  decryptUserData(encryptedPackage) {
    const iv = Buffer.from(encryptedPackage.iv, 'hex');
    const authTag = Buffer.from(encryptedPackage.authTag, 'hex');

    const decipher = crypto.createDecipheriv(
      SecureUserDataEncryptor.ALGORITHM,
      this.encryptionKey,
      iv
    );

    decipher.setAuthTag(authTag);

    let decrypted = decipher.update(encryptedPackage.data, 'hex', 'utf8');
    decrypted += decipher.final('utf8');

    return JSON.parse(decrypted);
  }
}

// Usage with externally managed key
