import org.slf4j.MDC;

public class SecureAuthenticationService {
    private static final Logger logger = LoggerFactory.getLogger(SecureAuthenticationService.class);
    private static final Logger securityLogger = LoggerFactory.getLogger("SECURITY_AUDIT");
    private static final String DB_URL = "jdbc:postgresql://localhost/userdb";
    private static final String DB_USER = "appuser";
    private static final String DB_PASS = "password";

    public boolean authenticate(HttpServletRequest request, String username, String password) {
        String clientIp = getClientIp(request);
        String userAgent = request.getHeader("User-Agent");
        String sessionId = request.getSession().getId();

        // Set MDC context for all log messages in this thread
        MDC.put("clientIp", clientIp);
        MDC.put("username", username);
        MDC.put("sessionId", sessionId);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            String sql = "SELECT user_id, password_hash, account_locked FROM users WHERE username = ?";
            PreparedStatement stmt = conn.prepareStatement(sql);
            stmt.setString(1, username);
            ResultSet rs = stmt.executeQuery();

            if (!rs.next()) {
                securityLogger.warn("LOGIN_FAILED: Unknown username attempt | ip={} | username={} | userAgent={}",
                    clientIp, username, userAgent);
                return false;
            }

            if (rs.getBoolean("account_locked")) {
                securityLogger.warn("LOGIN_BLOCKED: Locked account access attempt | ip={} | username={}",
                    clientIp, username);
                return false;
            }

            String storedHash = rs.getString("password_hash");
            int userId = rs.getInt("user_id");

            if (BCrypt.checkpw(password, storedHash)) {
                securityLogger.info("LOGIN_SUCCESS: User authenticated | ip={} | userId={} | username={}",
                    clientIp, userId, username);
                return true;
            } else {
                securityLogger.warn("LOGIN_FAILED: Invalid password | ip={} | userId={} | username={}",
                    clientIp, userId, username);
                return false;
            }
        } catch (SQLException e) {
            logger.error("DATABASE_ERROR: Authentication query failed | ip={} | username={} | error={}",
                clientIp, username, e.getMessage());
            securityLogger.error("AUTH_ERROR: Database failure during authentication | ip={} | username={}",
                clientIp, username);
            return false;
        } finally {
            MDC.clear();
        }
    }

    private String getClientIp(HttpServletRequest request) {
        String xForwardedFor = request.getHeader("X-Forwarded-For");
        if (xForwardedFor != null && !xForwardedFor.isEmpty()) {
            return xForwardedFor.split(",")[0].trim();
        }
        return request.getRemoteAddr();
    }
}

